create extension if not exists pgcrypto;create type public.user_role as enum('customer','admin');create type public.product_status as enum('draft','active','inactive','out_of_stock');create type public.order_status as enum('pending','paid','processing','shipped','completed','cancelled');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role public.user_role not null default 'customer',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,description text,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,sku text unique not null,description text,price numeric(14,2) not null default 0,discount_price numeric(14,2),stock integer not null default 0,weight_grams integer not null default 0,status public.product_status not null default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade not null,storage_path text not null,public_url text not null,is_primary boolean default false,created_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id) on delete set null,name text not null,email text unique not null,phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id) on delete set null,status public.order_status not null default 'pending',shipping_name text,shipping_phone text,shipping_address text,subtotal numeric(14,2) default 0,shipping_cost numeric(14,2) default 0,total numeric(14,2) default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade not null,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity integer not null,unit_price numeric(14,2) not null,subtotal numeric(14,2) not null);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table profiles enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table product_images enable row level security;alter table customers enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
create policy "public active categories" on categories for select to anon,authenticated using(is_active=true or is_admin());create policy "public active products" on products for select to anon,authenticated using(status='active' or is_admin());create policy "public product images" on product_images for select to anon,authenticated using(true);create policy "admin profiles" on profiles for all to authenticated using(is_admin() or id=auth.uid()) with check(is_admin() or id=auth.uid());create policy "admin categories" on categories for all to authenticated using(is_admin()) with check(is_admin());create policy "admin products" on products for all to authenticated using(is_admin()) with check(is_admin());create policy "admin images" on product_images for all to authenticated using(is_admin()) with check(is_admin());create policy "admin customers" on customers for all to authenticated using(is_admin()) with check(is_admin());create policy "admin orders" on orders for all to authenticated using(is_admin()) with check(is_admin());create policy "admin items" on order_items for all to authenticated using(is_admin()) with check(is_admin());
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do update set public=true;create policy "public image read" on storage.objects for select to public using(bucket_id='product-images');create policy "admin image upload" on storage.objects for insert to authenticated with check(bucket_id='product-images' and public.is_admin());create policy "admin image update" on storage.objects for update to authenticated using(bucket_id='product-images' and public.is_admin());create policy "admin image delete" on storage.objects for delete to authenticated using(bucket_id='product-images' and public.is_admin());
